def transform(grid):
    # Convert enclosed 9-cavities to 3 (wall cells are 0-marker); outside stays 9.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    from collections import deque
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r in (0,h-1) or c in (0,w-1)) and grid[r][c] == 9:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
